css:
:root {
  --line-color: var(--w-color, #930606);

  /*
   * Valor alternativo de tamaño 4:
   * 4 / 16 = 0.25 px en una altura de 40 px.
   */
  --line-thickness: 0.625%;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;

  background: transparent !important;
}

.line-widget,
.line-widget * {
  box-sizing: border-box;
}

.line-widget {
  position: relative;
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;

  background: transparent;
  pointer-events: none;
  user-select: none;
  opacity: var(--w-opacity, 1);
}

/* Línea centrada y adaptada a todo el ancho. */
.line-element {
  position: absolute;
  left: 0;
  top: 50%;

  width: 100%;
  height: var(--line-thickness);
  max-height: 100%;

  transform: translateY(-50%);

  border: none;
  border-radius: 999px;
  background: var(--line-color);
}

js:
"use strict";

(function () {
  const BASE_HEIGHT = 40;
  const DEFAULT_THICKNESS = 4;

  // Conversión: tamaño 8 equivale a 0.5 px.
  const THICKNESS_FACTOR = 0.5 / 8;

  let container = null;
  let lastUpdate = null;

  function getBaseThickness(widget) {
    const configuredSize = parseFloat(widget.fontSize);

    if (
      Number.isFinite(configuredSize) &&
      configuredSize > 0
    ) {
      return configuredSize;
    }

    const cssSize = parseFloat(
      getComputedStyle(container)
        .getPropertyValue("--w-font-size")
    );

    if (Number.isFinite(cssSize) && cssSize > 0) {
      return cssSize;
    }

    return DEFAULT_THICKNESS;
  }

  function render(w) {
    if (!container) return;

    const widget = w || {};

    // Color del apartado TEXTO.
    container.style.removeProperty("--line-color");

    if (
      typeof widget.color === "string" &&
      widget.color.trim() !== ""
    ) {
      container.style.setProperty(
        "--line-color",
        widget.color
      );
    }

    /*
     * Conversión para la altura base de 40 px:
     *
     * Tamaño 8  → 0.5 px
     * Tamaño 16 → 1 px
     * Tamaño 24 → 1.5 px
     * Tamaño 32 → 2 px
     *
     * El grosor también varía proporcionalmente
     * al modificar la altura del widget.
     */
    const baseThickness = getBaseThickness(widget);

    const convertedThickness =
      baseThickness * THICKNESS_FACTOR;

    const thicknessPercent =
      (convertedThickness / BASE_HEIGHT) * 100;

    container.style.setProperty(
      "--line-thickness",
      thicknessPercent + "%"
    );
  }

  window.onWidgetUpdate = function (w) {
    lastUpdate = w;
    render(w);
  };

  function initialize() {
    container = document.querySelector(".line-widget");

    if (!container) return;

    render(lastUpdate || window.WIDGET || null);
  }

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      initialize,
      { once: true }
    );
  } else {
    initialize();
  }
})();
